// Builtin functions read as values: tar-stream's `var alloc = Buffer.alloc`,
// fs.realpathSync stored and compared, and smol-toml's `''.isWellFormed`
// feature probe.
'use strict';
var fs = require('fs');
var alloc = Buffer.alloc;
var origRealpathSync = fs.realpathSync;
var HAS_WELLFORMED = !!''.isWellFormed;

exports.report = function report() {
  var header = alloc(8);
  var filled = alloc(5, 'ab');
  var numbered = alloc(3, 7);
  var out = [];
  out.push(header.length, header[0], filled.toString(), numbered[2], typeof alloc, alloc.length);
  try {
    alloc('8');
  } catch (error) {
    out.push(error.code);
  }
  out.push(origRealpathSync('/'), origRealpathSync === fs.realpathSync, typeof fs.realpathSync.native);
  out.push(Buffer.isBuffer(origRealpathSync('/', 'buffer')), origRealpathSync('/', { encoding: 'hex' }));
  out.push(fs.realpathSync.native('/'));
  try {
    origRealpathSync('/definitely/missing/path');
  } catch (error) {
    out.push(error.code);
  }
  out.push(HAS_WELLFORMED, 'ok'.isWellFormed(), typeof ''.toUpperCase);
  return out;
};

// The stored alloc with each fill form, and the stored realpathSync and
// realpathSync.native with file URLs.
var realpathNative = fs.realpathSync.native;
var url = require('url');
exports.more = function more() {
  var out = [];
  function attempt(label, fn) {
    try {
      var value = fn();
      out.push(label + ' ' + (Buffer.isBuffer(value) ? value.toString('hex') : value));
    } catch (error) {
      out.push(label + ' ' + error.name + ' ' + error.code + ' ' + error.message);
    }
  }
  attempt('hex', function () { return alloc(4, 'ab', 'hex'); });
  attempt('base64', function () { return alloc(4, 'YQ==', 'base64'); });
  attempt('latin1', function () { return alloc(3, '\u00e9', 'latin1'); });
  attempt('upper case', function () { return alloc(4, 'ab', 'UTF8'); });
  attempt('null encoding', function () { return alloc(4, 'ab', null); });
  attempt('buffer pattern', function () { return alloc(5, Buffer.from([1, 2, 3])); });
  attempt('uint16 pattern', function () { return alloc(4, new Uint16Array([0x0102])); });
  attempt('null fill', function () { return alloc(3, null); });
  attempt('true fill', function () { return alloc(3, true); });
  attempt('object fill', function () { return alloc(3, { valueOf: function () { return 258; } }); });
  attempt('negative fill', function () { return alloc(2, -1); });
  attempt('empty string', function () { return alloc(2, ''); });
  attempt('empty buffer', function () { return alloc(2, Buffer.alloc(0)); });
  attempt('no bytes', function () { return alloc(2, 'zz', 'hex'); });
  attempt('unknown encoding', function () { return alloc(2, 'ab', 'nope'); });
  attempt('number encoding', function () { return alloc(2, 'ab', 5); });
  attempt('empty size', function () { return alloc(0, 'ab', 'nope').length; });
  // Through call, as a wrapper forwarding its arguments passes them.
  var root = url.pathToFileURL('/');
  attempt('url', function () { return origRealpathSync.call(null, root); });
  attempt('native url', function () { return realpathNative.call(null, root); });
  attempt('http url', function () { return origRealpathSync.call(null, new URL('http://example.com/')); });
  attempt('native http url', function () { return realpathNative.call(null, new URL('http://example.com/')); });
  attempt('encoded slash', function () { return origRealpathSync.call(null, new URL('file:///a%2Fb')); });
  attempt('native number', function () { return realpathNative.call(null, 5); });
  attempt('native bytes', function () { return realpathNative.call(null, new Uint8Array(Buffer.from('/'))); });
  return out;
};
